import{_ as a,o,c as t,a2 as i}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Auth advanced III testing — v0.6 8 axis SSOT","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/auth-advanced-III-testing.md","filePath":"concepts/auth-advanced-III-testing.md"}'),d={name:"concepts/auth-advanced-III-testing.md"};function s(c,e,r,n,l,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="auth-advanced-iii-testing-—-v0-6-8-axis-ssot" tabindex="-1">Auth advanced III testing — v0.6 8 axis SSOT <a class="header-anchor" href="#auth-advanced-iii-testing-—-v0-6-8-axis-ssot" aria-label="Permalink to &quot;Auth advanced III testing — v0.6 8 axis SSOT&quot;">​</a></h1><h2 id="what-this-covers" tabindex="-1">What this covers <a class="header-anchor" href="#what-this-covers" aria-label="Permalink to &quot;What this covers&quot;">​</a></h2><p><code>@kiwa/auth</code> v0.6 layers 8 advanced Passwordless UX axes on top of the v0.4 / v0.5 base (4 protocol adapter = WebAuthn L3 + Passkey + OAuth 2.1 + OIDC). Each new axis models a semantic that browsers implement differently — device binding, conditional UI, step-up MFA, risk-based auth, auth continuity, cross-device flow, session hijack detection, and auth telemetry. This document is the SSOT for the 8 axes, the 3-platform fidelity grid (chromium / webkit / firefox), and the pair 第 1 pair 3 段拡張達成 record.</p><h2 id="pair-第-1-pair-3-段拡張達成" tabindex="-1">Pair 第 1 pair 3 段拡張達成 <a class="header-anchor" href="#pair-第-1-pair-3-段拡張達成" aria-label="Permalink to &quot;Pair 第 1 pair 3 段拡張達成&quot;">​</a></h2><p>v1.44 achieves the <strong>1st 縦深化 pair 3 段拡張</strong> (Auth base → v1.22 II → v1.44 III). This is the second pair to reach depth 3 (after Search v1.14→v1.15→v1.36), demonstrating that the 3-stage extension pattern is reproducible after the 4-stage depth-4 record was established (v1.40 AI/LLM / v1.41 Payment / v1.42 Observability).</p><h2 id="the-8-v0-6-advanced-passwordless-ux-axes" tabindex="-1">The 8 v0.6 advanced Passwordless UX axes <a class="header-anchor" href="#the-8-v0-6-advanced-passwordless-ux-axes" aria-label="Permalink to &quot;The 8 v0.6 advanced Passwordless UX axes&quot;">​</a></h2><h3 id="device-bound-passkey-axis" tabindex="-1">device-bound-passkey axis <a class="header-anchor" href="#device-bound-passkey-axis" aria-label="Permalink to &quot;device-bound-passkey axis&quot;">​</a></h3><p><code>startDevicePasskey</code> + <code>bindToDevice</code> + <code>verifySyncFabric</code> + <code>migrateCredential</code> + <code>confirmCredProps</code>. Models device-bound vs synced passkeys (Chrome Sync / iCloud Keychain / Firefox Sync ergonomics).</p><h3 id="conditional-ui-axis" tabindex="-1">conditional-ui axis <a class="header-anchor" href="#conditional-ui-axis" aria-label="Permalink to &quot;conditional-ui axis&quot;">​</a></h3><p><code>startConditionalUi</code> + <code>showHint</code> + <code>selectAutofill</code> + <code>triggerFallback</code> + <code>markTimeout</code>. Models WebAuthn L3 <code>mediation: &quot;conditional&quot;</code> autofill flows on 3 browsers.</p><h3 id="step-up-mfa-axis" tabindex="-1">step-up-mfa axis <a class="header-anchor" href="#step-up-mfa-axis" aria-label="Permalink to &quot;step-up-mfa axis&quot;">​</a></h3><p><code>startStepUp</code> + <code>requestEscalation</code> + <code>satisfyAal2</code> + <code>satisfyAal3</code> + <code>checkTrustCache</code>. Models NIST SP 800-63B AAL1 → AAL2 → AAL3 escalation ladder + trust duration cache.</p><h3 id="risk-based-auth-axis" tabindex="-1">risk-based-auth axis <a class="header-anchor" href="#risk-based-auth-axis" aria-label="Permalink to &quot;risk-based-auth axis&quot;">​</a></h3><p><code>startRiskEval</code> + <code>evaluateScore</code> + <code>injectChallenge</code> + <code>applyPolicy</code>. Models signal aggregation (device + IP + geo + velocity + behavioral) → adaptive challenge → allow/block policy.</p><h3 id="auth-continuity-axis" tabindex="-1">auth-continuity axis <a class="header-anchor" href="#auth-continuity-axis" aria-label="Permalink to &quot;auth-continuity axis&quot;">​</a></h3><p><code>startContinuity</code> + <code>seamlessReauth</code> + <code>rotateRefresh</code> + <code>extendSession</code> + <code>hitRevocationWindow</code>. Models RFC 6749 §10.4 refresh token rotation + revocation window.</p><h3 id="cross-device-flow-axis" tabindex="-1">cross-device-flow axis <a class="header-anchor" href="#cross-device-flow-axis" aria-label="Permalink to &quot;cross-device-flow axis&quot;">​</a></h3><p><code>startCrossDevice</code> + <code>generateQr</code> + <code>pairBle</code> + <code>openTunnel</code> + <code>completeHandshake</code>. Models CTAP2 hybrid transport (caBLE) desktop-with-phone flow.</p><h3 id="session-hijack-detect-axis" tabindex="-1">session-hijack-detect axis <a class="header-anchor" href="#session-hijack-detect-axis" aria-label="Permalink to &quot;session-hijack-detect axis&quot;">​</a></h3><p><code>startHijackWatch</code> + <code>reportFingerprintDrift</code> + <code>reportGeoAnomaly</code> + <code>reportConcurrentSession</code> + <code>triggerLogoutCascade</code>. Models per-session anomaly signals + cascade logout on confirmed hijack.</p><h3 id="auth-telemetry-axis" tabindex="-1">auth-telemetry axis <a class="header-anchor" href="#auth-telemetry-axis" aria-label="Permalink to &quot;auth-telemetry axis&quot;">​</a></h3><p><code>startAuthTelemetry</code> + <code>recordAttempt</code> + <code>updateSuccessRate</code> + <code>bucketLatency</code> + <code>detectAbuse</code>. Models operational metrics + abuse detection based on failure rate.</p><h2 id="_3-platform-×-8-axis-fidelity-grid" tabindex="-1">3-platform × 8-axis fidelity grid <a class="header-anchor" href="#_3-platform-×-8-axis-fidelity-grid" aria-label="Permalink to &quot;3-platform × 8-axis fidelity grid&quot;">​</a></h2><p><code>collectFidelityCoverage([&#39;chromium&#39;, &#39;webkit&#39;, &#39;firefox&#39;])</code> produces 24 rows (3 platform × 8 axis). Each row carries the neutral event list and browser-dialect map — e.g. device-bound-passkey axis maps <code>passkey.sync-fabric-verified</code> to <code>chrome_sync.passkey_verified</code> on chromium, <code>icloud_keychain.verified</code> on webkit, <code>ff_sync.passkey_verified</code> on firefox.</p><h2 id="dogfood-app-real-driver-env-gate" tabindex="-1">Dogfood app real-driver env-gate <a class="header-anchor" href="#dogfood-app-real-driver-env-gate" aria-label="Permalink to &quot;Dogfood app real-driver env-gate&quot;">​</a></h2><p>3 dogfood apps ship in v1.44 — one per operational cluster of axes.</p><ul><li><code>examples/dogfood-auth-passwordless-ux-app</code> — device-bound + conditional-ui + cross-device. <code>KIWA_MODE=real</code> + <code>AUTH_PASSWORDLESS_STACK_READY=1</code> + <code>KIWA_AUTH_PASSWORDLESS_URL</code> triggers real browser+WebAuthn stack.</li><li><code>examples/dogfood-auth-step-up-mfa-app</code> — step-up + continuity + hijack. <code>KIWA_MODE=real</code> + <code>AUTH_STEP_UP_STACK_READY=1</code> + <code>KIWA_AUTH_STEP_UP_URL</code>.</li><li><code>examples/dogfood-auth-risk-based-app</code> — risk + telemetry + hijack (concurrent + geo variant). <code>KIWA_MODE=real</code> + <code>AUTH_RISK_BASED_STACK_READY=1</code> + <code>KIWA_AUTH_RISK_BASED_URL</code>.</li></ul><p>Each dogfood runs the fidelity harness across 9 scenarios (3 platform × 3 stage) and reports mock-vs-real trace drift.</p><h2 id="related-concepts" tabindex="-1">Related concepts <a class="header-anchor" href="#related-concepts" aria-label="Permalink to &quot;Related concepts&quot;">​</a></h2><ul><li><code>real-driver-testing.md</code> (SSOT for <code>KIWA_MODE=real</code> env-gate pattern)</li><li><code>edge-serverless-advanced-testing.md</code> (v1.43 pair 第 12 new base pair introduction)</li><li><code>observability-advanced-III-testing.md</code> (v1.42 pair 第 11 depth-4 achievement)</li><li><code>release-invariants.md</code> (v1.29 3-layer defensive structure)</li></ul>',30)])])}const v=a(d,[["render",s]]);export{u as __pageData,v as default};
